   210	        .iter()
   211	        .filter(|question| question.active)
   212	        .collect::<Vec<_>>();
   213	    if active_questions.is_empty() {
   214	        return Ok(None);
   215	    }
   216	
   217	    let mut connection = open_database(path)?;
   218	    for _ in 0..16 {
   219	        let code = new_game_code().map_err(|_| rusqlite::Error::InvalidQuery)?;
   220	        let code_exists: bool = connection.query_row(
   221	            "SELECT EXISTS(SELECT 1 FROM games WHERE code = ?1)",
   222	            [&code],
   223	            |row| row.get(0),
   224	        )?;
   225	        if code_exists {
   226	            continue;
   227	        }
   228	
   229	        let transaction = connection.transaction()?;
   230	        transaction.execute(
   231	            "INSERT INTO games(quiz_id, quiz_title, code, status, current_position)
   232	             VALUES (?1, ?2, ?3, 'waiting', -1)",
   233	            params![quiz.id, quiz.title, code],
   234	        )?;
   235	        let game_id = transaction.last_insert_rowid();
   236	
   237	        for (position, question) in active_questions.iter().enumerate() {
   238	            transaction.execute(
   239	                "INSERT INTO game_questions(game_id, source_question_id, body, position)
   240	                 VALUES (?1, ?2, ?3, ?4)",
   241	                params![game_id, question.id, question.body, position as i64],
   242	            )?;
   243	            let game_question_id = transaction.last_insert_rowid();
   244	            for (option_position, option) in question.options.iter().enumerate() {
   245	                transaction.execute(
   246	                    "INSERT INTO game_options(game_question_id, body, is_correct, position)
   247	                     VALUES (?1, ?2, ?3, ?4)",
