   609	    for (const option of options || []) {
   610	      const item = document.createElement('li');
   611	      item.append(document.createTextNode(option.text));
   612	      if (results) {
   613	        const count = document.createElement('span');
   614	        count.className = 'option-result-count';
   615	        count.textContent = `Answers: ${option.answers || 0}`;
   616	        item.append(document.createTextNode(' '), count);
   617	        if (option.correct) {
   618	          const correct = document.createElement('strong');
   619	          correct.className = 'correct-label';
   620	          correct.textContent = 'Correct';
   621	          item.append(document.createTextNode(' '), correct);
   622	        }
   623	      }
   624	      list.append(item);
   625	    }
   626	  }
   627	  function render(state) {
   628	    byId('screen-title').textContent = state.title;
   629	    byId('join-link').textContent = state.join_url;
   630	    byId('player-count').textContent = `Players: ${state.players}`;
   631	    const hasQuestion = state.question_number !== null;
   632	    const progress = hasQuestion ? `Question ${state.question_number} of ${state.question_count}` : '';
   633	    byId('question-progress').textContent = progress;
   634	    byId('closed-progress').textContent = progress;
