   636	    byId('closed-question').textContent = state.question_text || '';
   637	    byId('answer-count').textContent = `Answers: ${state.answered} / ${state.players}`;
   638	    replaceOptions('open-options', state.options, false);
   639	    replaceOptions('closed-options', state.options, true);
   640	    show('waiting-stage', state.status === 'waiting');
   641	    show('open-stage', state.status === 'open');
   642	    show('closed-stage', state.status === 'closed');
   643	    show('over-stage', state.status === 'over');
   644	    const next = byId('next-button');
