fn render_option_list(options: &[GameOptionState], with_results: bool) -> String {
    let mut html = String::new();
    for option in options {
        html.push_str("<li>");
        html.push_str(&escape_html(&option.text));
        if with_results {
            html.push_str(&format!(
                " <span class=\"option-result-count\">Answers: {}</span>",
                option.answers.unwrap_or(0)
            ));
            if option.correct == Some(true) {
                html.push_str(" <strong class=\"correct-label\">Correct</strong>");
            }
        }
        html.push_str("</li>");
    }
    html
}

fn game_action_form(csrf: &str, action: &str, label: &str, button_id: Option<&str>) -> String {
    let id = button_id
        .map(|value| format!(" id=\"{value}\""))
        .unwrap_or_default();
    format!(
        "<form class=\"game-action\" method=\"post\" action=\"/moderate/games/{{GAME_ID}}/action\"><input type=\"hidden\" name=\"csrf\" value=\"{}\"><input class=\"game-action-name\" type=\"hidden\" name=\"action\" value=\"{action}\"><button class=\"btn btn--pink btn--lg\" type=\"submit\"{id}>{label}</button></form>",
        escape_html(csrf)
    )
}

