}

async fn create_quiz(State(state): State<AppState>, Form(form): Form<QuizForm>) -> Response {
    if !csrf_valid(&state, &form.csrf) {
        return csrf_error();
    }
    let title = form.title.trim();
    if title.is_empty() {
        return Html(render_quiz_form(
            &state,
            None,
            &form.title,
            form.number_of_winners,
            &["Title is required".to_owned()],
        ))
        .into_response();
    }
    if form.number_of_winners < 1 {
        return Html(render_quiz_form(
            &state,
            None,
            &form.title,
            form.number_of_winners,
            &["Number of winners must be at least 1".to_owned()],
        ))
        .into_response();
    }

    let result = (|| -> rusqlite::Result<i64> {
        let connection = open_database(&state.db_path)?;
        connection.execute(
            "INSERT INTO quizzes(title, number_of_winners) VALUES (?1, ?2)",
            params![title, form.number_of_winners],
        )?;
        Ok(connection.last_insert_rowid())
    })();
    match result {
        Ok(id) => Redirect::to(&format!("/moderate/quizzes/{id}")).into_response(),
        Err(error) => internal_error(error),
    }
}

async fn import_quiz_page(State(state): State<AppState>) -> Response {
    Html(render_import_quiz_form(&state, "", &[])).into_response()
}

async fn import_quiz(State(state): State<AppState>, Form(form): Form<ImportQuizForm>) -> Response {
    if !csrf_valid(&state, &form.csrf) {
        return csrf_error();
    }

    let transfer = match serde_json::from_str::<QuizTransfer>(&form.quiz_json) {
        Ok(transfer) => transfer,
        Err(error) => {
            return Html(render_import_quiz_form(
                &state,
                &form.quiz_json,
        Ok(Some(quiz)) => {
            let transfer = transfer_from_quiz(&quiz);
            match serde_json::to_string_pretty(&transfer) {
                Ok(json) => {
                    let content = format!(
                        "<div class=\"breadcrumbs\"><a href=\"/moderate/quizzes/{}\">← {}</a></div><div class=\"page-head\"><div><h1>Export quiz</h1><p class=\"meta\">Copy this JSON to move the quiz to another Quizzy app.</p></div></div><pre class=\"quiz-json\">{}</pre>",
                        quiz.id,
                        escape_html(&quiz.title),
                        escape_html(&json)
                    );
                    Html(page("Export quiz", &content)).into_response()
                }
                Err(error) => internal_error(error),
            }
        }
        Ok(None) => not_found(),
        Err(error) => internal_error(error),
    }
}

